import{_ as m,a0 as r,w as d,s as u,ao as l,I as i,a1 as a,A as n,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"用一些超酷的功能使 Vim 变得更强大 | LCTT x X-CMD","titleTemplate":false,"description":"用一些超酷的功能使 Vim 变得更强大 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用一些超酷的功能使 Vim 变得更强大 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用一些超酷的功能使 Vim 变得更强大 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171231 Making Vim Even More Awesome With These Cool Features","title":"用一些超酷的功能使 Vim 变得更强大","tag":"201802","desc":""},"relativePath":"201802/20171231 Making Vim Even More Awesome With These Cool Features.md","filePath":"[post].md"}'),p={name:"201802/20171231 Making Vim Even More Awesome With These Cool Features.md"};function s(V,e,w,T,f,c){const o=r("Link");return d(),u("div",null,[e[23]||(e[23]=l('<h1 id="用一些超酷的功能使-vim-变得更强大" tabindex="-1">用一些超酷的功能使 Vim 变得更强大 <a class="header-anchor" href="#用一些超酷的功能使-vim-变得更强大" aria-label="Permalink to “用一些超酷的功能使 Vim 变得更强大”">​</a></h1><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/making-vim-even-more-awesome-with-these-cool-features_orig.jpg" alt=""></p><p>Vim 是每个 Linux 发行版]中不可或缺的一部分，也是 Linux 用户最常用的工具（当然是基于终端的）。至少，这个说法对我来说是成立的。人们可能会在利用什么工具进行程序设计更好方面产生争议，的确 Vim 可能不是一个好的选择，因为有很多不同的 IDE 或其它类似于 Sublime Text 3，Atom 等使程序设计变得更加容易的成熟的文本编辑器。</p><h3 id="我的感想" tabindex="-1">我的感想 <a class="header-anchor" href="#我的感想" aria-label="Permalink to “我的感想”">​</a></h3><p>但我认为，Vim 应该从一开始就以我们想要的方式运作，而其它编辑器让我们按照已经设计好的方式工作，实际上不是我们想要的工作方式。我不会过多地谈论其它编辑器，因为我没有过多地使用过它们（我对 Vim 情有独钟）。</p><p>不管怎样，让我们用 Vim 来做一些事情吧，它完全可以胜任。</p><h3 id="利用-vim-进行程序设计" tabindex="-1">利用 Vim 进行程序设计 <a class="header-anchor" href="#利用-vim-进行程序设计" aria-label="Permalink to “利用 Vim 进行程序设计”">​</a></h3><h4 id="执行代码" tabindex="-1">执行代码 <a class="header-anchor" href="#执行代码" aria-label="Permalink to “执行代码”">​</a></h4><p>考虑一个场景，当我们使用 Vim 设计 C++ 代码并需要编译和运行它时，该怎么做呢。</p><p>(a). 我们通过 <code>Ctrl + Z</code> 返回到终端，或者利用 <code>:wq</code> 保存并退出。</p><p>(b). 但是任务还没有结束，接下来需要在终端上输入类似于 <code>g++ fileName.cxx</code> 的命令进行编译。</p><p>(c). 接下来需要键入 <code>./a.out</code> 执行它。</p><p>为了让我们的 C++ 代码在 shell 中运行，需要做很多事情。但这似乎并不是利用 Vim 操作的方法（ Vim 总是倾向于把几乎所有操作方法利用一两个按键实现）。那么，做这些事情的 Vim 的方式究竟是什么?</p><h4 id="vim-方式" tabindex="-1">Vim 方式 <a class="header-anchor" href="#vim-方式" aria-label="Permalink to “Vim 方式”">​</a></h4><p>Vim 不仅仅是一个文本编辑器，它是一种编辑文本的编程语言。这种帮助我们扩展 Vim 功能的编程语言是 “VimScript”（LCTT 译注： Vim 脚本）。</p><p>因此，在 VimScript 的帮助下，我们可以只需一个按键轻松地将编译和运行代码的任务自动化。</p>',16)),i("p",null,[a(o,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_orig.png"},{default:n(()=>[...e[0]||(e[0]=[i("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_orig.png",alt:"create functions in vim .vimrc"},null,-1)])]),_:1})]),e[24]||(e[24]=l('<p>以上是在我的 <code>.vimrc</code> 配置文件里创建的一个名为 <code>CPP()</code> 函数的片段。</p><h4 id="利用-vimscript-创建函数" tabindex="-1">利用 VimScript 创建函数 <a class="header-anchor" href="#利用-vimscript-创建函数" aria-label="Permalink to “利用 VimScript 创建函数”">​</a></h4><p>在 VimScript 中创建函数的语法非常简单。它以关键字 <code>func</code> 开头，然后是函数名（在 VimScript 中函数名必须以大写字母开头，否则 Vim 将提示错误）。在函数的结尾用关键词 <code>endfunc</code>。</p><p>在函数的主体中，可以看到 <code>exec</code> 语句，无论您在 <code>exec</code> 关键字之后写什么，都会在 Vim 的命令模式上执行（记住，就是在 Vim 窗口的底部以 <code>:</code> 开始的命令）。现在，传递给 <code>exec</code> 的字符串是（LCTT 译注：<code>:!clear &amp;&amp; g++ % &amp;&amp; ./a.out</code>） -</p>',4)),i("p",null,[a(o,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_1_orig.png"},{default:n(()=>[...e[1]||(e[1]=[i("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_1_orig.png",alt:"vim functions commands & symbols"},null,-1)])]),_:1})]),e[25]||(e[25]=l('<p>当这个函数被调用时，它首先清除终端屏幕，因此只能看到输出，接着利用 <code>g++</code> 执行正在处理的文件，然后运行由前一步编译而形成的 <code>a.out</code> 文件。</p><h4 id="将-ctrl-r-映射为运行-c-代码。" tabindex="-1">将 <code>Ctrl+r</code> 映射为运行 C++ 代码。 <a class="header-anchor" href="#将-ctrl-r-映射为运行-c-代码。" aria-label="Permalink to “将 Ctrl+r 映射为运行 C++ 代码。”">​</a></h4><p>我将语句 <code>call CPP()</code> 映射到键组合 <code>Ctrl+r</code>，以便我现在可以按 <code>Ctrl+r</code> 来执行我的 C++ 代码，无需手动输入<code>:call CPP()</code> ，然后按回车键。</p><h4 id="最终结果" tabindex="-1">最终结果 <a class="header-anchor" href="#最终结果" aria-label="Permalink to “最终结果”">​</a></h4><p>我们终于找到了 Vim 方式的操作方法。现在，你只需按一个（组合）键，你编写的 C++ 代码就输出在你的屏幕上，你不需要键入所有冗长的命令了。这也节省了你的时间。</p><p>我们也可以为其他语言实现这类功能。</p>',6)),i("p",null,[a(o,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_2_orig.png"},{default:n(()=>[...e[2]||(e[2]=[i("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_2_orig.png",alt:"create function in vim for python"},null,-1)])]),_:1})]),e[26]||(e[26]=i("p",null,[t("对于Python：您可以按下 "),i("code",null,"Ctrl+e"),t(" 解释执行您的代码。")],-1)),i("p",null,[a(o,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_3_orig.png"},{default:n(()=>[...e[3]||(e[3]=[i("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_3_orig.png",alt:"create function in vim for java"},null,-1)])]),_:1})]),e[27]||(e[27]=l('<p>对于Java：您现在可以按下 <code>Ctrl+j</code>，它将首先编译您的 Java 代码，然后执行您的 Java 类文件并显示输出。</p><h3 id="进一步提高" tabindex="-1">进一步提高 <a class="header-anchor" href="#进一步提高" aria-label="Permalink to “进一步提高”">​</a></h3><p>所以，这就是如何在 Vim 中操作的方法。现在，我们来看看如何在 Vim 中实现所有这些。我们可以直接在 Vim 中使用这些代码片段，而另一种方法是使用 Vim 中的自动命令 <code>autocmd</code>。<code>autocmd</code> 的优点是这些命令无需用户调用，它们在用户所提供的任何特定条件下自动执行。</p><p>我想用 <code>autocmd</code> 实现这个，而不是对每种语言使用不同的映射，执行不同程序设计语言编译出的代码。</p>',4)),i("p",null,[a(o,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_4_orig.png"},{default:n(()=>[...e[4]||(e[4]=[i("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_4_orig.png",alt:"autocmd in vimrc"},null,-1)])]),_:1})]),e[28]||(e[28]=l('<p>在这里做的是，为所有的定义了执行相应文件类型代码的函数编写了自动命令。</p><p>会发生什么？当我打开任何上述提到的文件类型的缓冲区， Vim 会自动将 <code>Ctrl + r</code> 映射到函数调用，而 <code>&lt;CR&gt;</code> 表示回车键，这样就不需要每完成一个独立的任务就按一次回车键了。</p><p>为了实现这个功能，您只需将函数片段添加到 <code>.vimrc</code> 文件中，然后将所有这些 <code>autocmd</code> 也一并添加进去。这样，当您下一次打开 Vim 时，Vim 将拥有所有相应的功能来执行所有具有相同绑定键的代码。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>就这些了。希望这些能让你更爱 Vim 。我目前正在探究 Vim 中的一些内容，正阅读文档，补充 <code>.vimrc</code> 文件，当我研究出一些成果后我会再次与你分享。</p>',5)),i("p",null,[e[6]||(e[6]=t("如果你想看一下我现在的 ",-1)),e[7]||(e[7]=i("code",null,".vimrc",-1)),e[8]||(e[8]=t(" 文件，这是我的 Github 账户的链接: ",-1)),a(o,{href:"https://github.com/phenomenal-ab/VIm-Configurations/blob/master/.vimrc"},{default:n(()=>[...e[5]||(e[5]=[t("MyVimrc",-1)])]),_:1}),e[9]||(e[9]=t("。",-1))]),e[29]||(e[29]=i("p",null,"期待你的好评。",-1)),e[30]||(e[30]=i("hr",null,null,-1)),i("p",null,[e[11]||(e[11]=t("via: ",-1)),a(o,{href:"http://www.linuxandubuntu.com/home/making-vim-even-more-awesome-with-these-cool-features"},{default:n(()=>[...e[10]||(e[10]=[t("http://www.linuxandubuntu.com/home/making-vim-even-more-awesome-with-these-cool-features",-1)])]),_:1})]),i("p",null,[e[15]||(e[15]=t("作者：",-1)),a(o,{href:"http://www.linuxandubuntu.com"},{default:n(()=>[...e[12]||(e[12]=[t("LINUXANDUBUNTU",-1)])]),_:1}),e[16]||(e[16]=t(" 译者：",-1)),a(o,{href:"https://github.com/stevenzdg988"},{default:n(()=>[...e[13]||(e[13]=[t("stevenzdg988",-1)])]),_:1}),e[17]||(e[17]=t(" 校对：",-1)),a(o,{href:"https://github.com/wxy"},{default:n(()=>[...e[14]||(e[14]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[20]||(e[20]=t("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[18]||(e[18]=[t("LCTT",-1)])]),_:1}),e[21]||(e[21]=t(" 原创编译，",-1)),a(o,{href:"https://linux.cn/"},{default:n(()=>[...e[19]||(e[19]=[t("Linux中国",-1)])]),_:1}),e[22]||(e[22]=t(" 荣誉推出",-1))])])}const v=m(p,[["render",s]]);export{h as __pageData,v as default};
